"""Install the X-equivalent manual test kit without running a sandbox test."""
import base64,hashlib,http.client,json,os,pathlib,pwd,shutil,stat,subprocess,time
P=pathlib.Path;BASE=P('/home/jwk/aenv-y-clean-20261111');DEST=BASE/'scripts'
BUNDLE={'run.sh': {'base64': '', 'sha256': '0f26828f52355c050e0a7cbaddf59f94c1d00d36a8b070c53fdc4f94af204994'}, 'benchmark_sandbox_lifecycle.py': {'base64': '', 'sha256': 'd4f5ea74fd01345dbf8df29b249bc8a4c0201a81fcbc10db4d6a5fbfcc1b30e9'}, 'check_aenv_fc_pool.py': {'base64': '', 'sha256': '51206c735d6871e5852366d58244c693a5f2b9fb1a5ca6b7d288832faf26e1a6'}, 'README.md': {'base64': '', 'sha256': 'dc6125b5b6e329dc65293634956f025c275ea07a388d68b572a38b56232d1b23'}}
def main():
 assert os.getuid()==os.geteuid()==0;os.umask(0o077)
 user=pwd.getpwnam('jwk');assert user.pw_uid==user.pw_gid==1002
 state=json.loads((BASE/'wikidata017/result.json').read_text());sid=state['templateId']
 assert state['buildStatus']['status']=='ready'
 key=(BASE/'config/api-key').read_text().strip()
 def api(path):
  conn=http.client.HTTPConnection('127.0.0.1',18080,timeout=20)
  try:
   conn.request('GET',path,headers={'X-API-Key':key});response=conn.getresponse();raw=response.read(1024**2)
   assert response.status in (200,204),'API status '+str(response.status)
   return response.status,json.loads(raw) if raw else None
  finally:conn.close()
 assert api('/health')[0]==204
 templates=api('/templates')[1];row=next(r for r in templates if r['templateID']==sid)
 assert row['cpuCount']==2 and row['memoryMB']==4096 and row.get('buildStatus','ready')=='ready'
 if not DEST.exists():DEST.mkdir(mode=0o700);os.chown(DEST,1002,1002)
 assert DEST.resolve()==DEST and DEST.is_dir() and DEST.stat().st_uid==1002
 assert not DEST.stat().st_mode&0o022,'Scripts directory writable by other users'
 receipt=BASE/'script-install020';assert not receipt.exists();receipt.mkdir(mode=0o700);os.chown(receipt,1002,1002)
 backups=receipt/'backups';backups.mkdir(mode=0o700);os.chown(backups,1002,1002)
 files={}
 for name,row in BUNDLE.items():
  raw=base64.b64decode(row['base64'],validate=True);assert hashlib.sha256(raw).hexdigest()==row['sha256'];files[name]=raw
 files['bench_image_map.json']=(json.dumps({'x1103-wikidata':sid},indent=2)+'\n').encode()
 legacy=P('/home/jwk/scripts');legacy_info={'exists':legacy.exists(),'symlink':legacy.is_symlink()}
 if legacy.exists() or legacy.is_symlink():
  st=legacy.lstat();legacy_info.update(uid=st.st_uid,gid=st.st_gid,mode=oct(stat.S_IMODE(st.st_mode)),resolved=str(legacy.resolve()))
 result={'action':'INSTALL_X_EQUIVALENT_MANUAL_TEST_KIT020','directory':str(DEST),'defaultRounds':10,'concurrency':100,'benchmarkExecuted':False,'backups':[],'files':{}}
 for name,raw in files.items():
  assert '/' not in name and name not in ('.','..')
  path=DEST/name;mode=0o700 if name.endswith(('.sh','.py')) else 0o600
  if path.exists() or path.is_symlink():
   st=path.lstat();assert stat.S_ISREG(st.st_mode) and st.st_uid==1002,'Existing foreign or linked file preserved'
   if path.read_bytes()==raw:result['files'][name]={'sha256':hashlib.sha256(raw).hexdigest(),'unchanged':True};continue
   saved=backups/name;saved.write_bytes(path.read_bytes());os.chown(saved,1002,1002);saved.chmod(stat.S_IMODE(st.st_mode));result['backups'].append(str(saved))
  temp=DEST/(name+'.install020.tmp');assert not temp.exists() and not temp.is_symlink()
  temp.write_bytes(raw);os.chown(temp,1002,1002);temp.chmod(mode);temp.replace(path)
  result['files'][name]={'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'bytes':len(raw)}
 assert result['files']['benchmark_sandbox_lifecycle.py']['sha256']=='d4f5ea74fd01345dbf8df29b249bc8a4c0201a81fcbc10db4d6a5fbfcc1b30e9'
 results=DEST/'results'
 if not results.exists():results.mkdir(mode=0o700);os.chown(results,1002,1002)
 assert results.resolve()==results and results.stat().st_uid==1002
 env={'PATH':'/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin','HOME':user.pw_dir,'USER':'jwk','LOGNAME':'jwk','LANG':'C.UTF-8','DRY_RUN':'1','ROUNDS':'10'}
 assert shutil.which('flock',path=env['PATH'])
 def command(args,timeout=60):
  r=subprocess.run(args,env=env,cwd=DEST,capture_output=True,text=True,timeout=timeout)
  assert r.returncode==0,{'code':r.returncode,'stderr':r.stderr[-4000:]};return r.stdout
 command(['bash','-n',str(DEST/'run.sh')])
 result['existingHomeScriptsPath']=legacy_info
 result['sdk']=json.loads(command(['runuser','-u','jwk','--',str(BASE/'sdk/g4-e2b246/bin/python'),'-I','-c',"import importlib.metadata as m,json;print(json.dumps({'e2b':m.version('e2b'),'pyqwest':m.version('pyqwest')}))"]))
 assert result['sdk']=={'e2b':'2.46.0','pyqwest':'0.10.0'}
 # Invoke the exact user command as root, exercising its automatic drop to jwk.
 result['dryRunOutput']=command(['bash',str(DEST/'run.sh')])
 run=next(line.split('Output: ',1)[1] for line in result['dryRunOutput'].splitlines() if line.startswith('Output: '))
 config=json.loads((P(run)/'config.json').read_text());plan=json.loads((P(run)/'plan.json').read_text())
 assert config['total']==config['batch_size']==100 and config['rounds']==10 and config['warmup_count']==1 and len(plan)==100
 assert (P(run)/'config.json').stat().st_uid==1002
 assert not (P(run)/'operations.jsonl').exists(),'Dry run unexpectedly executed requests'
 result.update(status='INSTALLED_DRY_RUN_PASSED',templateId=sid,dryRunDirectory=run,manualCommand='cd /home/jwk/aenv-y-clean-20261111/scripts && bash run.sh')
 result['finalInventoryCount']=len(api('/v2/sandboxes?limit=100')[1])
 path=receipt/'result.json';path.write_text(json.dumps(result,indent=2)+'\n');os.chown(path,1002,1002)
 print(json.dumps(result),flush=True)
if __name__=='__main__':main()
